/* Programmatic SEO pages (generated by the backend from the dashboard's Live templates) + sitemap/robots.
   A template page is served only when it is not thin and does not clash with a built-in page. */
import { builtInPages } from './pages';
import { overrideFor } from './seo';

/* path → template page with the dashboard's per-URL override merged in (null when not published) */
export function pseoPage(S, path) {
  if (builtInPages(S).has(path)) return null;
  const p = (S.seo.pages || []).find(x => x.path === path && x.status === 'Live' && !x.thin);
  if (!p) return null;
  const o = overrideFor(S, path) || {};
  return { ...p, title: o.title || p.title, meta: o.meta || p.meta, h1: o.h1 || p.h1, intro: o.intro || p.intro, faqs: (o.faqs && o.faqs.length) ? o.faqs : p.faqs, noindex: !!o.noindex, canonical: o.canonical || '' };
}

/* pages listed in sitemap.xml: indexable built-in pages + published template pages (same rules as the dashboard) */
export function sitemapPages(S) {
  const out = [];
  for (const b of builtInPages(S).values()) { const o = overrideFor(S, b.path) || {}; if (!o.noindex && !o.canonical) out.push({ path: b.path, prio: b.prio }); }
  const seen = new Set(out.map(p => p.path));
  for (const p of S.seo.pages || []) { if (seen.has(p.path)) continue; const q = pseoPage(S, p.path); if (q && !q.noindex && !q.canonical) { out.push({ path: q.path, prio: q.prio }); seen.add(q.path); } }
  return out;
}

export function sitemapXml(S) {
  const s = S.seo.settings || {};
  const D = 'https://' + String(s.domain || S.CONFIG.domain).replace(/^https?:\/\//, '').replace(/\/$/, '');
  const today = new Date().toISOString().slice(0, 10);
  const urls = sitemapPages(S).map(p => `  <url><loc>${D}${p.path}</loc><lastmod>${today}</lastmod><priority>${(+p.prio || 0.5).toFixed(1)}</priority></url>`);
  return `<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n${urls.join('\n')}\n</urlset>\n`;
}

const DEFAULT_ROBOTS = 'User-agent: *\nAllow: /\nDisallow: /admin/\nDisallow: /api/\n\nSitemap: https://{domain}/sitemap.xml';
export function robotsTxt(S) {
  const s = S.seo.settings || {}, domain = String(s.domain || S.CONFIG.domain).replace(/^https?:\/\//, '').replace(/\/$/, '');
  return String(s.robots || DEFAULT_ROBOTS).replace(/\{domain\}/g, domain).trim() + '\n';
}
